package cn.iocoder.yudao.module.hrm.service.payroll;
import static cn.iocoder.yudao.framework.test.core.util.AssertUtils.assertServiceException;
import static cn.iocoder.yudao.module.hrm.enums.ErrorCodeConstants.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import cn.iocoder.yudao.framework.test.core.ut.BaseDbUnitTest;
import cn.iocoder.yudao.framework.common.util.json.JsonUtils;
import cn.iocoder.yudao.module.hrm.controller.admin.payroll.vo.HrmPayrollCostRowVO;
import cn.iocoder.yudao.module.hrm.dal.dataobject.payroll.*;
import cn.iocoder.yudao.module.hrm.dal.dataobject.employee.info.HrmEmployeeDO;
import cn.iocoder.yudao.module.hrm.dal.dataobject.salary.monthrecord.*;
import cn.iocoder.yudao.module.hrm.dal.mysql.payroll.*;
import cn.iocoder.yudao.module.hrm.dal.mysql.salary.monthrecord.HrmSalaryMonthRecordMapper;
import java.math.*;
import java.time.*;
import java.util.*;
import javax.annotation.Resource;
import org.junit.jupiter.api.*;
import org.springframework.boot.test.mock.mockito.MockBean;
import org.springframework.context.annotation.Import;
@Import(HrmPayrollOverviewService.class)
class HrmPayrollOverviewServiceTest extends BaseDbUnitTest {
 @Resource HrmPayrollOverviewService service;
 @Resource HrmSalaryMonthRecordMapper batches;
 @Resource HrmPayrollRunMapper runs;
 @Resource HrmPayrollPaymentMapper payments;
 @Resource HrmPayrollInputIssueMapper issues;
 @MockBean HrmPayrollScopeService scope;
 @MockBean HrmPayrollEntityService entities;
 @MockBean HrmPayrollInputService inputs;
 @MockBean HrmPayrollReadinessService readiness;
 @MockBean HrmPayrollCostService costs;
 @MockBean HrmPayrollSupplementService supplements;
 Long batchId,runId;List<HrmSalaryMonthEmployeeRecordDO> rows;Map<String,Object> input,rules;
 BigDecimal n(String value){return new BigDecimal(value);}
 HrmSalaryMonthEmployeeRecordDO salary(Long id,String gross){List<HrmSalaryMonthEmployeeRecordDO.OptionValue> fees=new ArrayList<>();int[] codes={100101,100102,110101,120101};for(int code:codes)fees.add(new HrmSalaryMonthEmployeeRecordDO.OptionValue().setCode(code).setValue(n("100")));return new HrmSalaryMonthEmployeeRecordDO().setEmployeeId(id).setExpectedPaySalary(n(gross)).setPersonalTax(n("500")).setRealPaySalary(n(gross).subtract(n("700"))).setOptionValues(fees).setTaxSourceSnapshot("{\"policy\":{\"id\":1},\"profile\":{\"identifier\":\"private-tax-id\"}}");}
 @BeforeEach void setup(){HrmSalaryMonthRecordDO b=new HrmSalaryMonthRecordDO().setEntityId(10L).setTitle("十月常规").setYear(2026).setMonth(10).setBatchKey("REGULAR").setStatus(15).setExpectedPaySalary(n("999999"));batches.insert(b);batchId=b.getId();rows=Arrays.asList(salary(1L,"10000"),salary(2L,"20000"));input=new LinkedHashMap<>();input.put("employees",Arrays.asList(new HrmEmployeeDO().setId(1L).setName("历史员工甲").setJobNumber("E1"),new HrmEmployeeDO().setId(2L).setName("历史员工乙").setJobNumber("E2")));Map<String,Object> approved=new HashMap<>(),values=new HashMap<>(),insurance=new HashMap<>(),groups=new HashMap<>(),taxRules=new HashMap<>();for(Long id:Arrays.asList(1L,2L)){Map<String,Object> kinds=new HashMap<>();for(String k:HrmPayrollInputService.KINDS)kinds.put(k,Collections.singletonMap("status","APPROVED"));approved.put(id.toString(),kinds);values.put(id.toString(),Collections.singletonList(Collections.singletonMap("value","private-wage")));insurance.put(id.toString(),Collections.singletonMap("baseId",9));groups.put(id.toString(),Collections.singletonMap("id",5));taxRules.put(id.toString(),Collections.singletonMap("type",1));}input.put("approvedInputs",approved);input.put("salaryValues",values);input.put("insurancePolicySources",insurance);rules=new HashMap<>();rules.put("salaryGroups",groups);rules.put("taxRules",taxRules);HrmPayrollRunDO run=new HrmPayrollRunDO().setMonthRecordId(batchId).setVersion(1).setExpectedPaymentDate(LocalDate.of(2026,11,5)).setInputSnapshot(JsonUtils.toJsonString(input)).setRuleSnapshot(JsonUtils.toJsonString(rules)).setResultSnapshot(JsonUtils.toJsonString(rows));runs.insert(run);runId=run.getId();}
 void save(){runs.updateById(new HrmPayrollRunDO().setId(runId).setInputSnapshot(JsonUtils.toJsonString(input)).setRuleSnapshot(JsonUtils.toJsonString(rules)).setResultSnapshot(JsonUtils.toJsonString(rows)));}
 HrmPayrollOverviewService.Detail detail(){return service.detail(batchId,null,1L);}
 @Test void totalsComeFromImmutableResultsAndMissingCostIsUnknown(){HrmPayrollOverviewService.Summary s=detail().getSummary();assertEquals(0,n("30000").compareTo(s.getGross()));assertEquals(0,n("1000").compareTo(s.getTax()));assertEquals(0,n("28600").compareTo(s.getNet()));assertEquals(0,n("200").compareTo(s.getCorporateInsurance()));assertNull(s.getApprovedCost());assertEquals(2,s.getEmployeeCount());assertEquals(LocalDate.of(2026,11,5),s.getExpectedPaymentDate());}
 @Test void frozenReadinessUsesOnlySavedEvidenceAndNeverRechecksCurrentCumulative(){HrmPayrollOverviewService.Detail d=detail();assertEquals(20,d.getSignalCount());assertEquals(20,d.getReadyCount());assertEquals("历史员工甲",d.getEmployees().get(0).get("name"));verifyNoInteractions(readiness,inputs);String serialized=JsonUtils.toJsonString(d);assertFalse(serialized.contains("private-tax-id"));assertFalse(serialized.contains("private-wage"));assertFalse(serialized.contains("inputSnapshot"));}
 @Test void personnelFilterAppliesToWageCostPaymentsAndIssues(){when(costs.approvedReport(eq(batchId),eq(1L))).thenReturn(new HrmPayrollCostReportDO().setId(8L).setResultSnapshot(JsonUtils.toJsonString(Arrays.asList(new HrmPayrollCostRowVO().setEmployeeId(1L).setTotal(n("10400")),new HrmPayrollCostRowVO().setEmployeeId(2L).setTotal(n("20400"))))));payments.insert(new HrmPayrollPaymentDO().setMonthRecordId(batchId).setRunId(runId).setEmployeeId(1L).setEmployeeName("历史员工甲").setAttempt(1).setAmount(n("9300")).setStatus("SUCCESS").setBankAccount("private-bank"));payments.insert(new HrmPayrollPaymentDO().setMonthRecordId(batchId).setRunId(runId).setEmployeeId(2L).setEmployeeName("历史员工乙").setBankAccount("private-bank-2").setAttempt(1).setAmount(n("19300")).setStatus("FAILED"));issues.insert(new HrmPayrollInputIssueDO().setBatchId(batchId).setEmployeeId(2L).setKind("INSURANCE").setStatus("OPEN").setRequestKey("overview-issue"));HrmPayrollOverviewService.Summary s=service.detail(batchId,Collections.singleton(1L),1L).getSummary();assertEquals(0,n("10000").compareTo(s.getGross()));assertEquals(0,n("10400").compareTo(s.getApprovedCost()));assertEquals(0,n("9300").compareTo(s.getPaidAmount()));assertEquals(1,s.getPaymentSuccess());assertEquals(0,s.getPaymentFailed());assertEquals(0,s.getOpenIssues());assertFalse(JsonUtils.toJsonString(s).contains("private-bank"));assertEquals(10,service.detail(batchId,Collections.singleton(1L),1L).getSignalCount());}
 @Test void explicitZeroCostRemainsKnown(){when(costs.approvedReport(anyLong(),anyLong())).thenReturn(new HrmPayrollCostReportDO().setId(9L).setResultSnapshot("[]"));assertEquals(BigDecimal.ZERO,detail().getSummary().getApprovedCost());}
 @Test void draftWithoutRunDoesNotFabricateZeroWagesOrZeroReadiness(){HrmSalaryMonthRecordDO draft=new HrmSalaryMonthRecordDO().setEntityId(10L).setStatus(5).setBatchKey("REGULAR").setYear(2026).setMonth(11);batches.insert(draft);when(inputs.roster(any())).thenReturn(Collections.singletonList(new HrmEmployeeDO().setId(3L).setName("新员工")));when(readiness.inspect(eq(draft.getId()),eq(3L),anyString(),eq(1L))).thenAnswer(call->new HrmPayrollReadinessService.Signal().setEmployeeId(3L).setKind(call.getArgument(2)).setReady(false));HrmPayrollOverviewService.Detail d=service.detail(draft.getId(),null,1L);assertNull(d.getSummary().getGross());assertEquals(10,d.getSignalCount());assertEquals(0,d.getReadyCount());}
 @Test void currentTrialUsesLiveReadinessAndDetectsNewRosterOutsideOldTrial(){batches.updateById(new HrmSalaryMonthRecordDO().setId(batchId).setStatus(11));when(inputs.roster(any())).thenReturn(Arrays.asList(new HrmEmployeeDO().setId(1L),new HrmEmployeeDO().setId(2L),new HrmEmployeeDO().setId(3L)));when(readiness.inspect(anyLong(),anyLong(),anyString(),anyLong())).thenAnswer(call->new HrmPayrollReadinessService.Signal().setEmployeeId(call.getArgument(1)).setKind(call.getArgument(2)).setReady(true));HrmPayrollOverviewService.Detail d=service.detail(batchId,Collections.singleton(3L),1L);assertNull(d.getSummary().getGross());assertTrue(d.getSummary().getSourceStatus().contains("重新核算"));assertEquals(10,d.getReadyCount());verifyNoInteractions(costs);}
 @Test void historyFiltersBySubjectYearMonthStatusAndBatchType(){HrmSalaryMonthRecordDO supplement=new HrmSalaryMonthRecordDO().setEntityId(10L).setYear(2026).setMonth(10).setStatus(5).setBatchKey("SUPPLEMENT:overview").setParentBatchId(batchId);batches.insert(supplement);batches.insert(new HrmSalaryMonthRecordDO().setEntityId(20L).setYear(2026).setMonth(10).setStatus(5).setBatchKey("REGULAR"));assertEquals(2,service.history(10L,2026,10,null,null,1L).size());assertEquals(1,service.history(10L,2026,10,15,"REGULAR",1L).size());assertEquals(supplement.getId(),service.history(10L,2026,null,null,"SUPPLEMENT",1L).get(0).getBatchId());assertServiceException(()->service.history(10L,2026,13,null,null,1L),PAYROLL_FINANCIAL_INVALID);}
 @Test void unknownPersonnelAndScopeCannotLeakData(){assertServiceException(()->service.detail(batchId,Collections.singleton(99L),1L),PAYROLL_ENTITY_INVALID);doThrow(cn.iocoder.yudao.framework.common.exception.util.ServiceExceptionUtil.exception(PAYROLL_ENTITY_INVALID)).when(scope).check(any(),eq("READ"),eq(7L));assertServiceException(()->service.detail(batchId,null,7L),PAYROLL_ENTITY_INVALID);doThrow(cn.iocoder.yudao.framework.common.exception.util.ServiceExceptionUtil.exception(PAYROLL_ENTITY_INVALID)).when(entities).check(10L,"READ",7L);assertServiceException(()->service.history(10L,2026,null,null,null,7L),PAYROLL_ENTITY_INVALID);}
 @Test void manualVersionUsesNewResultsAndOriginalEvidence(){HrmPayrollRunDO next=new HrmPayrollRunDO().setMonthRecordId(batchId).setVersion(2).setExpectedPaymentDate(LocalDate.of(2026,11,5)).setInputSnapshot("{\"sourceRunId\":"+runId+"}").setRuleSnapshot("{}").setResultSnapshot(JsonUtils.toJsonString(Collections.singletonList(salary(1L,"11000"))));runs.insert(next);assertEquals(0,n("11000").compareTo(detail().getSummary().getGross()));assertEquals(10,detail().getReadyCount());assertEquals(next.getId(),detail().getSummary().getRunId());}
 @Test void cyclicOrForeignLineageAndDuplicateEmployeeResultsFail(){input.put("sourceRunId",runId);save();assertServiceException(this::detail,PAYROLL_VERSION_CONFLICT);input.remove("sourceRunId");rows=Arrays.asList(salary(1L,"1"),salary(1L,"2"));save();assertServiceException(this::detail,PAYROLL_VERSION_CONFLICT);}
 @Test void historicalMissingEvidenceStaysUnknownWithoutCurrentFallback(){input.remove("approvedInputs");input.remove("salaryValues");save();HrmPayrollOverviewService.Detail d=detail();assertEquals(10,d.getReadyCount());assertTrue(d.getSignals().stream().anyMatch(s->"SNAPSHOT_MISSING".equals(s.getStatus())));verifyNoInteractions(readiness,inputs);}
 @Test void supplementsDoNotRepeatMonthlyContributionsOrDemandMonthlyInputs(){batches.updateById(new HrmSalaryMonthRecordDO().setId(batchId).setParentBatchId(55L).setBatchKey("SUPPLEMENT:overview"));rows=Collections.singletonList(salary(1L,"2000").setOptionValues(Collections.emptyList()));save();HrmPayrollOverviewService.Detail d=detail();assertEquals(BigDecimal.ZERO,d.getSummary().getCorporateInsurance());assertEquals(1,d.getSignalCount());assertEquals("SUPPLEMENT",d.getSignals().get(0).getKind());verifyNoInteractions(readiness,inputs);}
 @Test void supplementaryDraftUsesActualPreparationWithoutMonthlyReadiness(){batches.updateById(new HrmSalaryMonthRecordDO().setId(batchId).setStatus(5).setParentBatchId(55L).setBatchKey("SUPPLEMENT:overview"));when(supplements.readiness(batchId,1L)).thenReturn(Collections.singletonMap(1L,true));HrmPayrollOverviewService.Detail d=service.detail(batchId,Collections.singleton(1L),1L);assertEquals(1,d.getReadyCount());verifyNoInteractions(readiness,inputs);}

}
